import datetime
import time

class HydrationMonitor:
    def __init__(self):
        self.total_intake_ml = 0
        self.dawn_hour = 5  # Approximate dawn (5 AM); adjust as needed
        self.max_daily_ml = 3000
        self.penalty_points = 0
        self.bloat_threshold = 2500  # ml before bloating nags start

    def get_current_time(self):
        return datetime.datetime.now()

    def is_past_dawn(self):
        now = self.get_current_time()
        return now.hour >= self.dawn_hour

    def log_intake(self, amount_ml):
        if amount_ml <= 0:
            print("Invalid intake amount.")
            return

        now = self.get_current_time()
        self.total_intake_ml += amount_ml

        if self.is_past_dawn():
            penalty = amount_ml * 0.5  # Penalize 0.5 points per ml after dawn
            self.penalty_points += penalty
            print(f"⚠️ PENALTY: +{penalty:.1f} points for drinking after dawn ({now.strftime('%H:%M')}).")
            print("Remember: fluid intake past dawn is discouraged in this monitor.")

        # Bloating nag
        if self.total_intake_ml > self.bloat_threshold:
            nag_level = min((self.total_intake_ml - self.bloat_threshold) // 200 + 1, 5)
            print(f"💧 NAG REMINDER #{nag_level}: You're at {self.total_intake_ml}ml. Feeling bloated yet? Stop drinking or deal with the consequences.")

        print(f"Current total: {self.total_intake_ml}ml | Penalty score: {self.penalty_points:.1f}")

    def show_status(self):
        print(f"\n=== Hydration Status ===")
        print(f"Total intake: {self.total_intake_ml}ml")
        print(f"Penalty points (higher = worse): {self.penalty_points:.1f}")
        if self.penalty_points > 500:
            print("Severe penalty: You've been warned about post-dawn intake multiple times.")

